Your expense tracker is below. Add an item with its amount, category and date, set a monthly budget, and see the total and a split by category. Entries are saved on this device if your app allows it.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><style>
body{font-family:Segoe UI,sans-serif;margin:0;padding:12px;background:#fafaf7;color:#222;font-size:14px}
h2{margin:0 0 8px;font-size:18px}
.row{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px}
input,select,button{padding:7px;border:1px solid #ccc;border-radius:6px;font-size:14px}
button{background:#2f7d5b;color:#fff;border:0;cursor:pointer}
button.x{background:none;color:#b00;padding:2px 6px}
.card{background:#fff;border:1px solid #e3e3dc;border-radius:10px;padding:10px;margin-bottom:10px}
.big{font-size:22px;font-weight:600}
.bar{height:8px;background:#e8e8e0;border-radius:4px;overflow:hidden;margin:3px 0 8px}
.bar i{display:block;height:100%;background:#2f7d5b}
.over{color:#b00}
.item{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #eee;padding:5px 0}
.muted{color:#777;font-size:12px}
</style></head><body>
<h2>Monthly expenses</h2>
<div class="card">
  <div class="row">
    <input id="d" placeholder="What for?" style="flex:2;min-width:110px">
    <input id="a" type="number" min="0" placeholder="Amount (₹)" style="flex:1;min-width:90px">
    <select id="c"><option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Other</option></select>
    <input id="dt" type="date">
    <button onclick="add()">Add</button>
  </div>
  <div class="row"><span>Monthly budget (₹)</span><input id="b" type="number" min="0" style="width:110px" onchange="setB()"></div>
</div>
<div class="card">
  <div class="muted">Spent in <span id="mn"></span></div>
  <div class="big" id="tot">₹0</div>
  <div class="bar"><i id="bb" style="width:0"></i></div>
  <div id="left" class="muted"></div>
</div>
<div class="card"><b>By category</b><div id="cats" style="margin-top:6px"></div></div>
<div class="card"><b>This month's entries</b><div id="list"></div></div>
<script>
var S={items:[],budget:0};
try{var r=localStorage.getItem('exp1');if(r)S=JSON.parse(r)}catch(e){}
function save(){try{localStorage.setItem('exp1',JSON.stringify(S))}catch(e){}}
function inr(n){return '₹'+Math.round(n).toLocaleString('en-IN')}
var today=new Date().toISOString().slice(0,10);
document.getElementById('dt').value=today;
document.getElementById('b').value=S.budget||'';
function add(){
  var d=document.getElementById('d').value.trim(),a=parseFloat(document.getElementById('a').value);
  if(!d||!(a>0))return;
  S.items.push({id:Date.now(),d:d,a:a,c:document.getElementById('c').value,dt:document.getElementById('dt').value||today});
  document.getElementById('d').value='';document.getElementById('a').value='';
  save();draw();
}
function del(id){S.items=S.items.filter(function(x){return x.id!==id});save();draw()}
function setB(){S.budget=parseFloat(document.getElementById('b').value)||0;save();draw()}
function draw(){
  var m=today.slice(0,7),mi=S.items.filter(function(x){return x.dt.slice(0,7)===m}).sort(function(a,b){return b.dt.localeCompare(a.dt)});
  var t=mi.reduce(function(s,x){return s+x.a},0);
  document.getElementById('mn').textContent=new Date().toLocaleString('en-IN',{month:'long',year:'numeric'});
  document.getElementById('tot').textContent=inr(t);
  var p=S.budget?Math.min(100,t/S.budget*100):0;
  document.getElementById('bb').style.width=p+'%';
  var l=document.getElementById('left');
  if(S.budget){var r=S.budget-t;l.className='muted'+(r<0?' over':'');l.textContent=r>=0?inr(r)+' left of '+inr(S.budget):inr(-r)+' over budget of '+inr(S.budget)}else{l.textContent='Set a budget to see what is left.'}
  var by={};mi.forEach(function(x){by[x.c]=(by[x.c]||0)+x.a});
  var h='';Object.keys(by).sort(function(a,b){return by[b]-by[a]}).forEach(function(k){
    h+='<div style="display:flex;justify-content:space-between"><span>'+k+'</span><span>'+inr(by[k])+'</span></div><div class="bar"><i style="width:'+(by[k]/t*100)+'%"></i></div>'});
  document.getElementById('cats').innerHTML=h||'<span class="muted">Nothing yet.</span>';
  var o='';mi.forEach(function(x){
    o+='<div class="item"><div>'+esc(x.d)+'<div class="muted">'+x.c+' · '+x.dt+'</div></div><div>'+inr(x.a)+' <button class="x" onclick="del('+x.id+')">✕</button></div></div>'});
  document.getElementById('list').innerHTML=o||'<span class="muted">No entries this month.</span>';
}
function esc(s){return s.replace(/[&<>"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
draw();
</script></body></html>
```
